<?php
require_once __DIR__ . '/config/config.php'; require_once __DIR__ . '/config/helpers.php'; require_login();
$farmerId=(int)($_GET['farmer_id']??0);$farmers=$pdo->query('SELECT id,name,phone,district FROM farmers ORDER BY name')->fetchAll();$districtRows=districts($pdo);$weights=[];foreach($districtRows as $d)$weights[$d['district']]=(float)$d['sack_weight_kg'];
$form=['farmer_id'=>$farmerId,'paddy_type'=>'Nadu','gross_weight_kg'=>'','price_per_kg'=>'120','status'=>'Paid','bill_date'=>date('Y-m-d')];
if($farmerId){$s=$pdo->prepare('SELECT district FROM farmers WHERE id=?');$s->execute([$farmerId]);$fd=$s->fetchColumn();if($fd)$form['district']=$fd;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf($_POST['csrf']??null); $form=array_merge($form,$_POST);
 $fid=(int)($_POST['farmer_id']??0);$gross=(float)($_POST['gross_weight_kg']??0);$price=(float)($_POST['price_per_kg']??0);$district=trim($_POST['district']??'Vavuniya');$sack=(float)($_POST['sack_weight']??($weights[$district]??72));$sacks=$sack>0?floor($gross/$sack):0;$sackTotal=$sacks*$sack;$net=max($gross-$sackTotal,0);$total=$gross*$price;
 if(!$fid||$gross<=0||$price<=0){flash('error','Select a farmer and enter valid gross weight and price.');redirect('bill_create.php');}
 $s=$pdo->prepare('INSERT INTO bills(bill_number,farmer_id,bill_date,paddy_type,gross_weight_kg,sack_weight_kg,sack_count,net_weight_kg,price_per_kg,total_amount,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');
 $s->execute([next_bill_number($pdo),$fid,$form['bill_date'],$form['paddy_type'],$gross,$sack,$sacks,$net,$price,$total,$form['status'],current_user()['id']]);$newId=(int)$pdo->lastInsertId();flash('success','Bill created successfully.');redirect('bill_view.php?id='.$newId);
}
$pageTitle='Create New Bill';include __DIR__.'/includes/header.php';
?><script>window.districtWeights=<?=json_encode($weights)?>;</script><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-section"><h2>Farmer Details</h2><div class="form-grid three"><div class="field"><label>Farmer</label><select name="farmer_id" id="farmer_id" required onchange="document.getElementById('farmer_hint').textContent=this.options[this.selectedIndex].dataset.phone||''"><option value="">Select farmer</option><?php foreach($farmers as $f):?><option data-phone="<?=e($f['phone'])?>" value="<?=$f['id']?>" <?=($form['farmer_id']==$f['id']?'selected':'')?>><?=e($f['name'])?></option><?php endforeach;?></select><small id="farmer_hint" style="color:#6b7280"></small></div><div class="field"><label>Phone Number</label><input id="farmer_phone" readonly value=""></div><div class="field"><label>District</label><select name="district" id="district"><?php foreach($districtRows as $d):?><option <?=($form['district']??'Vavuniya')===$d['district']?'selected':''?>><?=e($d['district'])?></option><?php endforeach;?></select></div></div></div><div class="form-section"><h2>Paddy Details</h2><div class="form-grid three"><div class="field"><label>Paddy Type</label><select name="paddy_type"><option>Nadu</option><option <?=($form['paddy_type']==='Samba'?'selected':'')?>>Samba</option><option <?=($form['paddy_type']==='Keeri Samba'?'selected':'')?>>Keeri Samba</option></select></div><div class="field"><label>Gross Weight</label><input id="gross_weight" name="gross_weight_kg" type="number" step="0.01" min="0" value="<?=e((string)($form['gross_weight_kg']??''))?>" required></div><div class="field"><label>Price Per KG</label><input id="price_per_kg" name="price_per_kg" type="number" step="0.01" min="0" value="<?=e((string)$form['price_per_kg'])?>" required></div><div class="field"><label>Sack Weight</label><input id="sack_weight" name="sack_weight" type="number" step="0.01" min="1" value="<?=e((string)($weights[$form['district']??'Vavuniya']??72))?>" required><small style="color:#6b7280">Auto-filled from district, editable when needed.</small></div><div class="field"><label>Bill Date</label><input type="date" name="bill_date" value="<?=e($form['bill_date'])?>" required></div><div class="field"><label>Status</label><select name="status"><option>Paid</option><option>Due</option></select></div></div></div><div class="form-section"><h2>Calculation</h2><div class="calc-grid"><div class="calc-box"><div class="label">Number of Sacks</div><div class="value" id="preview_sacks">0</div></div><div class="calc-box"><div class="label">Sack Weight Total</div><div class="value" id="preview_sack_total">0 kg</div></div><div class="calc-box"><div class="label">Net / Remainder Weight</div><div class="value" id="preview_net">0 kg</div></div></div><div class="total-box"><div><div style="opacity:.75;font-size:12px">Total Payment</div><strong id="preview_total">Rs. 0.00</strong></div><button class="btn btn-warning" type="submit">Generate Bill</button></div></div></form><script>document.getElementById('district')?.addEventListener('change',()=>{const f=document.querySelector('#farmer_id option:checked');});document.getElementById('farmer_id')?.addEventListener('change',e=>{const o=e.target.options[e.target.selectedIndex];document.getElementById('farmer_phone').value=o?.dataset.phone||'';});document.getElementById('farmer_id')?.dispatchEvent(new Event('change'));</script><?php include __DIR__.'/includes/footer.php'; ?>
